\label{tab:regression}
\begin{tabular}{llccc}
\toprule
\textbf{Model} & \textbf{Predictors} & \textbf{McFadden $R^2$} & \textbf{Nagelkerke $R^2$} & \textbf{Key OR} \\
\midrule
M1 & subject acc.\ $\Delta$ & 0.0007 & 0.0012 & 1.55 [1.19, 2.03] \\
